 internal sealed class MediaEditorRow : INotifyPropertyChanged {
  public event PropertyChangedEventHandler PropertyChanged;
  internal string Path, Hash; internal bool Image; internal Dictionary<string,string> Original, Values;
  internal string Error="", Info="",CoverMime; internal byte[] OriginalCover,Cover;
  public string Name {get{return System.IO.Path.GetFileName(Path);}}
  public string Title {get{return Value(Image?"[Image.Title]":"[MP3.Title]");}}
  public string Artist {get{return Value(Image?"[Image.Author]":"[MP3.Artist]");}}
  public string Album {get{return Value(Image?"[EXIF.Date]":"[MP3.Album]");}}
  public string State {get{return Error.Length>0?Error:Dirty?L.Text("mediaEditor.modified"):L.Text("attributes.unchanged");}}
  internal bool CoverChanged {get{return !SameCover(OriginalCover,Cover);}} internal static bool SameCover(byte[] a,byte[] b){return a==null?b==null:b!=null&&a.SequenceEqual(b);}
  internal bool Dirty {get{return Original!=null&&(CoverChanged||Values.Any(x=>!Original.ContainsKey(x.Key)||Original[x.Key]!=x.Value));}}
  internal string Value(string key){string value;return Values!=null&&Values.TryGetValue(key,out value)?value:"";}
  internal void Update(){var h=PropertyChanged;if(h!=null)foreach(string key in new[]{"Title","Artist","Album","State"})h(this,new PropertyChangedEventArgs(key));}
 }
