  static readonly string[][] ImageFields={new[]{"[Image.Title]","details.title"},new[]{"[Image.Author]","details.author"},new[]{"[Image.Comment]","details.comment"},new[]{"[Image.Copyright]","details.copyright"},new[]{"[EXIF.Date]","details.taken"},new[]{"[EXIF.Time]","mediaEditor.time"},new[]{"[EXIF.Make]","details.cameraMake"},new[]{"[EXIF.Model]","details.camera"}};
  internal MediaEditorWindow(Window owner,string[] paths,Action refresh,Action<bool> activity,Action<MediaMetadataRow> logged,Action<string[]> rename){
   this.refresh=refresh??delegate{};this.activity=activity??delegate{};this.logged=logged;this.rename=rename;
   CopyUi.Style(this,owner,L.Text("mediaEditor.title"),1440);Height=820;MinWidth=850;MinHeight=600;SizeToContent=SizeToContent.Manual;ResizeMode=ResizeMode.CanResize;DialogGeometry.Bound(this,1440,820,900,600);
   var body=new DockPanel();CopyUi.SectionedSurface(this,body);
   var top=new StackPanel();DockPanel.SetDock(top,Dock.Top);body.Children.Add(top);
