   var maskRow=new DockPanel{Margin=new Thickness(0,6,0,4)};top.Children.Add(maskRow);var parse=CopyUi.Button(L.Text("mediaEditor.fromName"),delegate{ParseSelected();});DockPanel.SetDock(parse,Dock.Right);maskRow.Children.Add(parse);DockPanel.SetDock(overwrite,Dock.Right);maskRow.Children.Add(overwrite);var insertToken=CopyUi.Button(L.Text("rename.insertToken"),delegate{TokenDropdown.Show(Mask);});DockPanel.SetDock(insertToken,Dock.Right);maskRow.Children.Add(insertToken);DockPanel.SetDock(masks,Dock.Left);maskRow.Children.Add(masks);masks.SelectionChanged+=delegate{if(masks.SelectedItem!=null)Mask.Text=(string)masks.SelectedItem;};TokenDropdown.Attach(Mask,MediaNames.WritableTokens.Concat(new[]{"[Ignore]"}));maskRow.Children.Add(Mask);
   top.Children.Add(new TextBlock{Text=L.Text("mediaEditor.maskHelp"),Foreground=FluentTheme.Muted,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,6)});
