   SaveButton=CopyUi.Button(L.Text("mediaNames.apply"),delegate{Work=Save();});bottom.Children.Add(SaveButton);
   bottom.Children.Add(CopyUi.Button(L.Text("mediaNames.rename"),delegate{if(running)return;var selected=Selected().Select(x=>x.Path).ToArray();if(selected.Length==0||!ConfirmDiscard())return;allowClose=true;Close();if(rename!=null)rename(selected);}));
