   var editor=EditorGrid;fieldPanel=editor;for(int i=0;i<4;i++)editor.ColumnDefinitions.Add(new ColumnDefinition());editor.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(190)});for(int i=0;i<3;i++)editor.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});DockPanel.SetDock(editor,Dock.Top);body.Children.Add(editor);
   foreach(var group in new[]{AudioFields,ImageFields})for(int index=0;index<group.Length;index++){var field=group[index];string key=field[0];var cell=new StackPanel{Margin=new Thickness(0,0,8,3)};cells[key]=cell;Grid.SetColumn(cell,index%4);Grid.SetRow(cell,index/4);editor.Children.Add(cell);var label=CopyUi.Label(L.Text(field[1]));label.Margin=new Thickness(0,1,0,1);label.TextTrimming=TextTrimming.CharacterEllipsis;label.ToolTip=L.Text(field[1]);labels[key]=label;cell.Children.Add(label);var box=new TextBox{Margin=new Thickness(0,0,2,0),Tag=key};Fields[key]=box;var line=new DockPanel{Tag=key};if(key!="[EXIF.Date]"&&key!="[EXIF.Time]"){var clear=CopyUi.Button("×",delegate{foreach(var row in Selected().Where(x=>x.Values.ContainsKey(key))){row.Values[key]="";row.Error="";row.Update();}ShowSelection();});clear.ToolTip=L.Text("mediaEditor.clearField");clear.MinWidth=28;clear.Width=28;DockPanel.SetDock(clear,Dock.Right);line.Children.Add(clear);}line.Children.Add(box);cell.Children.Add(line);box.TextChanged+=delegate{if(updating||running)return;foreach(var row in Selected().Where(x=>x.Values!=null&&x.Values.ContainsKey(key))){row.Values[key]=box.Text;row.Error="";row.Update();}UpdateStatus();};}
   coverPanel.Margin=new Thickness(4,0,0,0);coverPanel.Children.Add(CopyUi.Label(L.Text("mediaEditor.cover")));coverPanel.Children.Add(coverImage);var coverButtons=new StackPanel();coverPanel.Children.Add(coverButtons);coverButtons.Children.Add(CopyUi.Button(L.Text("mediaEditor.chooseCover"),delegate{ChooseCover();}));coverButtons.Children.Add(CopyUi.Button(L.Text("mediaEditor.clearCover"),delegate{foreach(var row in Selected().Where(x=>!x.Image)){row.Cover=null;row.CoverMime=null;row.Update();}ShowSelection();}));Grid.SetColumn(coverPanel,4);Grid.SetRowSpan(coverPanel,3);editor.Children.Add(coverPanel);
   info.TextWrapping=TextWrapping.Wrap;info.Margin=new Thickness(4,0,0,0);info.TextTrimming=TextTrimming.CharacterEllipsis;info.MaxHeight=170;Grid.SetColumn(info,4);Grid.SetRowSpan(info,3);editor.Children.Add(info);
   var columns=new GridView();foreach(var c in new[]{new[]{"rename.fileNameLabel","Name","230"},new[]{"details.title","Title","180"},new[]{"details.artist","Artist","150"},new[]{"details.album","Album","150"},new[]{"common.status","State","200"}})columns.Columns.Add(new GridViewColumn{Header=L.Text(c[0]),Width=Int32.Parse(c[2]),DisplayMemberBinding=new Binding(c[1])});List.View=columns;body.Children.Add(List);List.SizeChanged+=delegate{double width=Math.Max(0,List.ActualWidth-SystemParameters.VerticalScrollBarWidth-8);if(width>300){var weights=new[]{.25,.21,.17,.17,.20};for(int i=0;i<weights.Length;i++)columns.Columns[i].Width=Math.Floor(width*weights[i]);}};
