   Loaded+=delegate{Work=Load(paths);};SaveButton.IsEnabled=false;
  }
  MediaEditorRow[] Selected(){return List.SelectedItems.Cast<MediaEditorRow>().Where(x=>x.Values!=null).ToArray();}
  void ShowCategory(){bool image=category.SelectedIndex==1;updating=true;foreach(var pair in cells){bool visible=image?pair.Key.StartsWith("[Image.")||pair.Key.StartsWith("[EXIF."):pair.Key.StartsWith("[MP3.");pair.Value.Visibility=visible?Visibility.Visible:Visibility.Collapsed;}coverPanel.Visibility=image?Visibility.Collapsed:Visibility.Visible;info.Visibility=image?Visibility.Visible:Visibility.Collapsed;masks.ItemsSource=image?new[]{"[EXIF.Date]_[EXIF.Time] - [Image.Title]","[Image.Author] - [Image.Title]","[Image.Title]"}:new[]{"[MP3.Artist] - [MP3.Track] - [MP3.Title]","[MP3.Artist] - [MP3.Title]","[MP3.Track] - [MP3.Title]","[MP3.Artist] - [MP3.Album] - [MP3.Year] - [MP3.Track] - [MP3.Title]"};masks.SelectedIndex=0;var view=(GridView)List.View;view.Columns[2].Header=L.Text(image?"details.author":"details.artist");view.Columns[3].Header=L.Text(image?"details.taken":"details.album");List.ItemsSource=rows.Where(x=>x.Image==image).ToArray();if(List.Items.Count>0)List.SelectedIndex=0;updating=false;ShowSelection();}
  void ShowSelection(){updating=true;var selected=Selected();foreach(var pair in Fields){var values=selected.Where(x=>x.Values.ContainsKey(pair.Key)).Select(x=>x.Value(pair.Key)).Distinct(StringComparer.Ordinal).ToArray();pair.Value.IsEnabled=values.Length>0;pair.Value.Text=values.Length==1?values[0]:"";pair.Value.ToolTip=values.Length>1?L.Text("mediaEditor.mixed"):null;labels[pair.Key].Text=L.Text((AudioFields.Concat(ImageFields).First(x=>x[0]==pair.Key))[1])+(values.Length>1?" — "+L.Text("mediaEditor.mixed"):"");}coverPanel.IsEnabled=selected.Length>0;coverImage.Source=null;if(selected.Length>0&&!selected[0].Image&&selected.All(x=>MediaEditorRow.SameCover(x.Cover,selected[0].Cover))&&selected[0].Cover!=null)try{using(var stream=new MemoryStream(selected[0].Cover)){var bmp=new BitmapImage();bmp.BeginInit();bmp.CacheOption=BitmapCacheOption.OnLoad;bmp.DecodePixelWidth=240;bmp.StreamSource=stream;bmp.EndInit();bmp.Freeze();coverImage.Source=bmp;}}catch(Exception){}info.Text=selected.Length==1?selected[0].Info:"";info.ToolTip=info.Text;updating=false;UpdateStatus();}
  void ChooseCover(){var picker=new Microsoft.Win32.OpenFileDialog{Filter="JPEG / PNG (*.jpg;*.jpeg;*.png)|*.jpg;*.jpeg;*.png"};if(picker.ShowDialog(this)!=true)return;try{var fi=new FileInfo(picker.FileName);if(fi.Length>8L*1048576)throw new IOException(L.Text("mediaEditor.coverLimit"));byte[] bytes=File.ReadAllBytes(picker.FileName);string mime=bytes.Length>8&&bytes[0]==0x89&&bytes[1]==0x50&&bytes[2]==0x4e&&bytes[3]==0x47?"image/png":bytes.Length>3&&bytes[0]==0xff&&bytes[1]==0xd8&&bytes[2]==0xff?"image/jpeg":null;if(mime==null)throw new IOException(L.Text("mediaEditor.coverInvalid"));using(var stream=new MemoryStream(bytes)){var decoder=BitmapDecoder.Create(stream,BitmapCreateOptions.PreservePixelFormat,BitmapCacheOption.None);if(decoder.Frames.Count==0||(long)decoder.Frames[0].PixelWidth*decoder.Frames[0].PixelHeight>40000000)throw new IOException(L.Text("mediaEditor.coverInvalid"));}foreach(var row in Selected().Where(x=>!x.Image)){row.Cover=bytes;row.CoverMime=mime;row.Error="";row.Update();}ShowSelection();}catch(Exception ex){MessageBox.Show(this,ex.Message,Title);}}
  void UpdateStatus(){SaveButton.IsEnabled=!running&&rows.Any(x=>x.Dirty);status.Text=L.Format("mediaEditor.pending",rows.Count(x=>x.Dirty),rows.Count);}
  bool ConfirmDiscard(){return !rows.Any(x=>x.Dirty)||MessageBox.Show(this,L.Text("mediaEditor.discard"),Title,MessageBoxButton.YesNo,MessageBoxImage.Question)==MessageBoxResult.Yes;}
  void ParseSelected(){if(running)return;foreach(var row in Selected()){try{var parsed=MediaNames.Parse(System.IO.Path.GetFileNameWithoutExtension(row.Path),Mask.Text);if(parsed.Keys.Any(k=>row.Image?!k.StartsWith("[Image.")&&!k.StartsWith("[EXIF."):!k.StartsWith("[MP3.")))throw new IOException(L.Text("mediaNames.wrongType"));foreach(var value in parsed)if(overwrite.IsChecked==true||String.IsNullOrWhiteSpace(row.Value(value.Key)))row.Values[value.Key]=value.Value;row.Error="";}catch(Exception ex){row.Error=ex.Message;}row.Update();}ShowSelection();}
  static MediaEditorRow ReadRow(string path,CancellationToken token){var row=new MediaEditorRow{Path=path,Image=MediaNames.IsImage(path)};try{token.ThrowIfCancellationRequested();if(!MediaNames.Supported(path))throw new IOException(L.Text("mediaNames.unsupported"));PathSafety.RejectLinks(path);using(var input=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read)){row.Hash=MediaNames.Hash(input,token);using(var source=new RenameMetadata.MetadataSource(path,token))using(var file=TagLib.File.Create(source,TagLib.ReadStyle.None)){row.Original=MediaNames.Read(file);row.Values=new Dictionary<string,string>(row.Original);row.Info=L.Text("column.size")+": "+input.Length.ToString("N0")+" B";if(!row.Image){var picture=(file.Tag.Pictures??new TagLib.IPicture[0]).FirstOrDefault(x=>x.Type==TagLib.PictureType.FrontCover);if(picture!=null){row.OriginalCover=picture.Data.Data;row.Cover=row.OriginalCover;row.CoverMime=picture.MimeType;row.Info+="\n"+L.Text("mediaEditor.coverPresent");}}else{var tag=file.Tag as TagLib.Image.CombinedImageTag;if(tag!=null)foreach(var item in new[]{new[]{"ISOSpeedRatings","details.iso"},new[]{"FNumber","details.aperture"},new[]{"ExposureTime","details.exposure"},new[]{"FocalLength","details.focalLength"},new[]{"Latitude","details.latitude"},new[]{"Longitude","details.longitude"}}){try{var property=tag.GetType().GetProperty(item[0]);object value=property==null?null:property.GetValue(tag,null);if(value!=null&&!String.IsNullOrWhiteSpace(Convert.ToString(value)))row.Info+="\n"+L.Text(item[1])+": "+value;}catch(Exception){}}}}}
   if(row.Image)try{using(var stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read)){var decoder=BitmapDecoder.Create(stream,BitmapCreateOptions.PreservePixelFormat,BitmapCacheOption.None);var frame=decoder.Frames[0];row.Info+="\n"+L.Text("details.dimensions")+": "+frame.PixelWidth+" × "+frame.PixelHeight+"\n"+L.Text("details.pixelFormat")+": "+frame.Format;}}catch(Exception){}
   }catch(OperationCanceledException){throw;}catch(Exception ex){row.Error=ex.Message;}return row;}
  async Task Load(string[] paths){if(paths.Length>500){status.Text=L.Text("mediaNames.batchLimit");return;}running=true;activity(true);cancellation=new CancellationTokenSource();SaveButton.IsEnabled=false;try{var found=await Task.Run(()=>paths.Distinct(StringComparer.OrdinalIgnoreCase).Select(x=>ReadRow(x,cancellation.Token)).ToArray(),cancellation.Token);if(closed)return;rows.Clear();rows.AddRange(found);category.SelectedIndex=rows.Any(x=>!x.Image)?0:1;if(category.SelectedIndex>=0)ShowCategory();}catch(OperationCanceledException){}finally{running=false;activity(false);cancellation.Dispose();cancellation=null;UpdateStatus();}}
  async Task Save(){if(running)return;var pending=rows.Where(x=>x.Dirty).ToArray();if(pending.Length==0)return;
   var plans=pending.Select(x=>new {Row=x,Values=x.Values.Where(p=>!x.Original.ContainsKey(p.Key)||x.Original[p.Key]!=p.Value).ToDictionary(p=>p.Key,p=>p.Value)}).ToArray();
   running=true;activity(true);fieldPanel.IsEnabled=List.IsEnabled=category.IsEnabled=false;SaveButton.IsEnabled=false;cancellation=new CancellationTokenSource();try{
    var preview=await Task.Run(()=>plans.Select(x=>{var p=MediaNames.PreviewValues(x.Row.Path,x.Values,true,cancellation.Token);p.CoverChanged=x.Row.CoverChanged;p.Cover=x.Row.Cover;p.CoverMime=x.Row.CoverMime;return p;}).ToArray(),cancellation.Token);
    bool bad=false;for(int i=0;i<plans.Length;i++){var plan=plans[i];var p=preview[i];if(p.Changes==null||p.Hash!=plan.Row.Hash){plan.Row.Error=p.Changes==null?p.Status:L.Text("mediaNames.changed");plan.Row.Update();bad=true;}}
    if(bad){status.Text=L.Text("mediaEditor.fixErrors");return;}bool confirmed;
#if APP_TESTS
    if(ConfirmForTests!=null)confirmed=ConfirmForTests(pending.Length);else
#endif
    confirmed=MessageBox.Show(this,L.Format("mediaNames.confirm",pending.Length),Title,MessageBoxButton.YesNo,MessageBoxImage.Question)==MessageBoxResult.Yes;if(!confirmed)return;
    for(int i=0;i<plans.Length;i++){cancellation.Token.ThrowIfCancellationRequested();var p=preview[i];try{await Task.Run(()=>MediaNames.Apply(p,cancellation.Token));var reloaded=await Task.Run(()=>ReadRow(p.Path,CancellationToken.None));plans[i].Row.Hash=reloaded.Hash;plans[i].Row.Original=reloaded.Original;plans[i].Row.Values=reloaded.Values;plans[i].Row.OriginalCover=reloaded.OriginalCover;plans[i].Row.Cover=reloaded.Cover;plans[i].Row.CoverMime=reloaded.CoverMime;plans[i].Row.Error=reloaded.Error;plans[i].Row.Info=reloaded.Info;}catch(OperationCanceledException){throw;}catch(Exception ex){plans[i].Row.Error=p.Status=ex.Message;}if(logged!=null)logged(p);plans[i].Row.Update();}refresh();
   }catch(OperationCanceledException){refresh();status.Text=L.Text("mediaNames.cancelled");}finally{running=false;activity(false);fieldPanel.IsEnabled=List.IsEnabled=category.IsEnabled=true;cancellation.Dispose();cancellation=null;ShowSelection();}}
 }
